using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CustodyReturnTests
{
    static readonly EntityId Ward=new("created:ward");
    static EntityId Root(WorldSession s)=>s.DiagnosticSnapshot().Custody!.Entries.First().Input.Id;
    static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.Code+":"+r.VisibleReason);
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static CommandResult Act(WorldSession s,CustodyAction action,string? id=null)=>s.ManageCustody(new(new(id??"request:return/"+s.Revision),action,Original:Root(s)),s.PlayerControl,s.Revision);
    static WorldSession Depart(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.StartReturn));At(s,s.Seconds+2);return s;}
    static long Arrival(WorldSession s)=>s.DiagnosticSnapshot().Branches!.Journeys.Last(j=>j.Actor==s.PlayerControl).Legs[^1].EndAt;
    static void Together(WorldSession s){var a=s.GetBranchView(s.PlayerControl);var b=s.GetBranchView(Ward);Assert.Equal(a.Position,b.Position);Assert.Equal(a.NextPosition,b.NextPosition);var nearby=Assert.Single(s.GetNearbyActors(s.PlayerControl),x=>x.Actor==Ward);Assert.Equal(b.Position,nearby.Position);Assert.Equal(b.Walking,nearby.Walking);var w=s.DiagnosticSnapshot();Assert.Equal(w.Locations.Single(l=>l.Actor==s.PlayerControl) with{Actor=Ward},w.Locations.Single(l=>l.Actor==Ward));}
    [Fact]public void SameJourneyReachesHomeButNeedsExplicitReceipt(){var s=Depart();Together(s);At(s,Arrival(s)+1);Together(s);Assert.True(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));Good(Act(s,CustodyAction.ReceiveReturn));Assert.False(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));Assert.Equal(new EntityId("site:kofu"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Ward).Site);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void ActualIntermediateDisplayUsesSharedJourney(){var s=Depart();At(s,s.Seconds+50);Together(s);Assert.True(s.GetBranchView(Ward).Walking);Assert.Single(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==s.PlayerControl&&j.Legs[0].From=="castle");Assert.DoesNotContain(s.DiagnosticSnapshot().Branches!.Journeys,j=>j.Actor==Ward);}
    [Fact]public void DepartAndReceiptAreIdempotent(){var s=CustodySuccessionTests.Held();Good(Act(s,CustodyAction.StartReturn,"request:trip-once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CustodyAction.StartReturn,"request:trip-once").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.StartReturn).Code);At(s,s.Seconds+2);At(s,Arrival(s)+1);Good(Act(s,CustodyAction.ReceiveReturn,"request:receipt-once"));Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CustodyAction.ReceiveReturn,"request:receipt-once").Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ReceiveReturn).Code);}
    [Fact]public void CannotReceiveBeforeArrivalOrReleaseAtOriginalSiteAfterDeparture(){var s=Depart();Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ReceiveReturn).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.Release).Code);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ResumeReturn).Code);}
    [Fact]public void UnrelatedTravelCannotAbandonTheWard(){var s=Depart();At(s,Arrival(s)+1);var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:abandon","castle"),s.Revision).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void OrdinaryTravelAfterReceiptLeavesWardAtReturnedHome(){var s=Depart();At(s,Arrival(s)+1);Good(Act(s,CustodyAction.ReceiveReturn));Good(s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:leave-returned","castle"),s.Revision));At(s,s.Seconds+20);Assert.NotEqual(s.GetBranchView(s.PlayerControl).Position,s.GetBranchView(Ward).Position);Assert.Equal(NationalRoutes.Nodes.Single(n=>n.Id=="kofu").Position,s.GetBranchView(Ward).Position);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void OriginalGuaranteeAndDeadlineDoNotChange(){var s=CustodySuccessionTests.Held();var root=s.DiagnosticSnapshot().Custody!.Entries.First();Good(Act(s,CustodyAction.StartReturn));At(s,s.Seconds+2);At(s,Arrival(s)+1);Good(Act(s,CustodyAction.ReceiveReturn));Assert.Equal(root,s.DiagnosticSnapshot().Custody!.Entries.First());Assert.DoesNotContain(s.DiagnosticSnapshot().Custody!.Entries,e=>e.Input.Action==CustodyAction.Release);}
    [Fact]public void AbsentCurrentRecipientHoldsActualArrival(){var s=CustodySuccessionTests.Succeeded();Good(Act(s,CustodyAction.Reconfirm));Good(Act(s,CustodyAction.StartReturn));At(s,s.Seconds+2);At(s,Arrival(s)+1);Together(s);Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ReceiveReturn).Code);Assert.True(HostageCustody.HeldAt(s.DiagnosticSnapshot(),Ward,s.Seconds,s.Revision+1));}
    [Theory][InlineData("location")][InlineData("destination")][InlineData("travel")][InlineData("request")]
    public void ForgedEscortCannotLoad(string kind){var s=Depart();At(s,s.Seconds+10);var w=s.DiagnosticSnapshot();int n=Array.FindLastIndex(w.Custody!.Entries,e=>e.Return!=null);var e=w.Custody.Entries[n];if(kind=="location")w.Locations=w.Locations.Select(l=>l.Actor==Ward?l with{ProgressMm=l.ProgressMm+1}:l).ToArray();if(kind=="destination")w.Custody.Entries[n]=e with{Return=e.Return! with{Destination=new("site:odawara")}};if(kind=="travel")w.Custody.Entries[n]=e with{Return=e.Return! with{Travel=e.Return.Travel with{WorkSeconds=e.Return.Travel.WorkSeconds+1}}};if(kind=="request")w.Requests=w.Requests.Where(r=>r.Id!=e.Return!.Travel.RequestId).ToArray();Assert.ThrowsAny<Exception>(()=>new WorldSession(w));}
    static WorldSession Stopped(){var s=CustodySuccessionTests.Held();var w=s.DiagnosticSnapshot();var edges=BranchRoutes.GraphEdges(w).Where(e=>e.From=="castle"||e.To=="castle").ToArray();w.Couriers=w.Couriers! with{Conditions=edges.Select(e=>new RoadCondition(w.ElapsedSeconds+1,e.Id,true)).Concat(edges.Select(e=>new RoadCondition(w.ElapsedSeconds+20,e.Id,false))).OrderBy(e=>e.At).ThenBy(e=>e.Edge,StringComparer.Ordinal).ToArray()};s=new(w);Good(Act(s,CustodyAction.StartReturn));At(s,s.Seconds+2);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Last().Execution);Together(s);return s;}
    static void Resume(WorldSession s){At(s,s.Seconds+30);foreach(var edge in BranchRoutes.GraphEdges(s.DiagnosticSnapshot()).Where(e=>e.From=="castle"||e.To=="castle"))Good(s.InspectRoad(s.PlayerControl,edge.Id,s.Revision));Good(Act(s,CustodyAction.ResumeReturn));At(s,s.Seconds+2);Together(s);}
    [Fact]public void ActualClosedRoadStopsBothAndReopeningAllowsSameDestination(){var s=Stopped();Assert.Equal(ResultCode.NotAvailable,Act(s,CustodyAction.ResumeReturn).Code);Resume(s);At(s,Arrival(s)+1);Together(s);Good(Act(s,CustodyAction.ReceiveReturn));new WorldSession(s.DiagnosticSnapshot());}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)]
    public void ActualRecoveryKeepsEscortPositionAndFuture(int phase){var s=phase>=4?Stopped():Depart();if(phase==1)At(s,s.Seconds+50);if(phase is 2 or 3){At(s,Arrival(s)+1);if(phase==3)Good(Act(s,CustodyAction.ReceiveReturn));}if(phase==5)Resume(s);s.SetPaused(true);Together(s);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"custody-return-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"return",w.WorldId).Published);var host=new WorldSessionHost(CustodySuccessionTests.Held());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("return"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Together(host.Current);var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,$"custody-return-{phase}.before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,$"custody-return-{phase}.restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Fact]public void ReturnedWardCanJoinOrdinaryTravelFromActualHome(){var s=Depart();At(s,Arrival(s)+1);Good(Act(s,CustodyAction.ReceiveReturn));Good(s.ManageCompanion(new(new("request:returned-agree"),Ward,CompanionAction.Agree,Amount:20),s.PlayerControl,s.Revision));Good(s.ManageCompanion(new(new("request:returned-walk"),Ward,CompanionAction.TravelTogether,Destination:"castle"),s.PlayerControl,s.Revision));At(s,s.Seconds+10);Assert.Equal(s.GetBranchView(s.PlayerControl).Position,s.GetBranchView(Ward).Position);At(s,Arrival(s)+1);Assert.Equal(new EntityId("site:castle"),s.DiagnosticSnapshot().Locations.Single(l=>l.Actor==Ward).Site);new WorldSession(s.DiagnosticSnapshot());}
    [Fact]public void StaleStartDoesNotCreateAnEscort(){var s=CustodySuccessionTests.Held();var bytes=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.StateChanged,s.ManageCustody(new(new("request:stale-return"),CustodyAction.StartReturn,Original:Root(s)),s.PlayerControl,s.Revision-1).Code);Assert.Equal(bytes,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ForgedReceiptRecipientCannotLoad(){var s=Depart();At(s,Arrival(s)+1);Good(Act(s,CustodyAction.ReceiveReturn));var w=s.DiagnosticSnapshot();int n=w.Custody!.Entries.Length-1;w.Custody.Entries[n]=w.Custody.Entries[n] with{AcceptedBy=new EntityId("person:nobunaga")};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

}
